<script setup lang="ts">
const tastings = await useContentFetch<TastingView[]>('/api/tastings');
usePageSeo({ title: 'Proeverijen', description: 'De agenda en het archief van de proeverijen van Pour Decisions.' });

const route = useRoute();
const tab = computed(() => (route.query.tab === 'archief' ? 'archief' : 'aankomend'));
const visible = computed(() => tastings.value.filter(t => t.isUpcoming === (tab.value === 'aankomend')));

const tabs = [
  { key: 'aankomend', label: 'Aankomend', to: '/proeverijen' },
  { key: 'archief', label: 'Archief', to: { path: '/proeverijen', query: { tab: 'archief' } } },
] as const;
</script>

<template>
  <div>
    <PageHeader
      title="Proeverijen"
      kicker="Agenda"
      intro="Het volgende thema en wat er is geweest. Aankomend of archief volgt automatisch uit de datum."
    />

    <div class="container-page pb-14">
      <nav
        aria-label="Aankomend of archief"
        class="inline-flex gap-1 rounded-full bg-line p-1"
      >
        <NuxtLink
          v-for="item in tabs"
          :key="item.key"
          :to="item.to"
          :aria-current="tab === item.key ? 'page' : undefined"
          class="rounded-full px-4 py-2 text-sm font-semibold aria-[current=page]:bg-oak aria-[current=page]:text-white"
        >
          {{ item.label }}
        </NuxtLink>
      </nav>

      <div
        v-if="visible.length"
        class="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-3"
      >
        <TastingCard
          v-for="tasting in visible"
          :key="tasting.slug"
          :tasting="tasting"
        />
      </div>
      <p
        v-else-if="tab === 'aankomend'"
        class="mt-6 text-smoke"
      >
        Nog geen proeverij gepland.
      </p>
      <p
        v-else
        class="mt-6 text-smoke"
      >
        Het archief is nog leeg.
      </p>
    </div>
  </div>
</template>
